package com.learnspace.config;
import com.learnspace.model.*; import com.learnspace.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.LocalDate;
@Configuration public class SeedData { @Bean CommandLineRunner seed(UserRepository users, CourseRepository courses, BatchRepository batches, LessonRepository lessons, PasswordEncoder encoder){return x->{ if(courses.count()>0)return; AppUser admin=new AppUser();admin.setDisplayName("LearnSpace Admin");admin.setEmail("admin@learnspace.local");admin.setPassword(encoder.encode("ChangeMe123!"));admin.setRole(Role.ADMIN);users.save(admin);
 Course a=course("Full-Stack Web Development","Ananya Sharma","Development","Beginner","Build modern websites from first line of code to deployment.",4999); Course b=course("Data Analytics with Python","Rahul Verma","Data Science","Intermediate","Turn raw data into confident business decisions.",5999); courses.save(a);courses.save(b);
 batch(batches,a,"October 2026 Evening Batch","Mon, Wed & Fri · 7:00 PM",LocalDate.of(2026,10,5),30); batch(batches,a,"November 2026 Weekend Batch","Sat & Sun · 10:00 AM",LocalDate.of(2026,11,7),25); batch(batches,b,"October 2026 Pro Batch","Tue & Thu · 8:00 PM",LocalDate.of(2026,10,6),20);
 lesson(lessons,a,"Welcome & course roadmap","https://www.youtube.com/embed/UB1O30fR-EE","08:42",1);lesson(lessons,a,"HTML foundations","https://www.youtube.com/embed/UB1O30fR-EE","34:10",2);lesson(lessons,a,"CSS layouts in practice","https://www.youtube.com/embed/UB1O30fR-EE","42:28",3); lesson(lessons,b,"Python setup and notebooks","https://www.youtube.com/embed/rfscVS0vtbw","25:30",1);lesson(lessons,b,"Cleaning your first dataset","https://www.youtube.com/embed/rfscVS0vtbw","41:05",2);};}
 private Course course(String t,String i,String c,String l,String d,double p){Course x=new Course();x.setTitle(t);x.setInstructor(i);x.setCategory(c);x.setLevel(l);x.setDescription(d);x.setPrice(p);return x;} private void batch(BatchRepository r,Course c,String n,String s,LocalDate d,int seats){Batch b=new Batch();b.setCourse(c);b.setName(n);b.setSchedule(s);b.setStartDate(d);b.setSeats(seats);r.save(b);} private void lesson(LessonRepository r,Course c,String t,String u,String d,int p){Lesson l=new Lesson();l.setCourse(c);l.setTitle(t);l.setVideoUrl(u);l.setDuration(d);l.setPosition(p);r.save(l);} }
